#!/usr/bin/env python3
"""
Fix all translation files — add missing keys and translate untranslated values.
Uses built-in translation dictionaries instead of API calls for reliability.
"""
import json
import os
import copy

MESSAGES_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'apps', 'web', 'messages')

def load_json(lang):
    with open(os.path.join(MESSAGES_DIR, f'{lang}.json'), 'r', encoding='utf-8') as f:
        return json.load(f)

def save_json(lang, data):
    with open(os.path.join(MESSAGES_DIR, f'{lang}.json'), 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')

def get_value(obj, key_path):
    keys = key_path.split('.')
    cur = obj
    for k in keys:
        cur = cur[k]
    return cur

def set_value(obj, key_path, value):
    keys = key_path.split('.')
    cur = obj
    for k in keys[:-1]:
        if k not in cur:
            cur[k] = {}
        cur = cur[k]
    cur[keys[-1]] = value

def has_key(obj, key_path):
    keys = key_path.split('.')
    cur = obj
    for k in keys:
        if k not in cur:
            return False
        cur = cur[k]
    return True

