def fix_all_translations():
    en = load_json('en')
    
    # Get all language codes
    lang_files = [f for f in os.listdir(MESSAGES_DIR) if f.endswith('.json') and f != 'en.json']
    lang_codes = sorted([f.replace('.json', '') for f in lang_files])
    
    stats = {}
    
    for lang in lang_codes:
        data = load_json(lang)
        changes = 0
        
        # 1. Add missing keys
        for key_path, translations in MISSING_KEYS.items():
            if lang in translations:
                if not has_key(data, key_path):
                    set_value(data, key_path, translations[lang])
                    changes += 1
        
        # 2. Translate untranslated values (same as English)
        def fix_untranslated(en_obj, lang_obj, prefix=''):
            nonlocal changes
            for k, v in en_obj.items():
                full_key = f'{prefix}.{k}' if prefix else k
                if isinstance(v, dict):
                    if k in lang_obj and isinstance(lang_obj[k], dict):
                        fix_untranslated(v, lang_obj[k], full_key)
                    # If whole section missing, don't handle here (would need deep merge)
                else:
                    if k in lang_obj and lang_obj[k] == v and v:
                        # Check if we have a translation
                        if v in COMMON:
                            if lang in COMMON[v]:
                                lang_obj[k] = COMMON[v][lang]
                                changes += 1
                        # Check if key is in MISSING_KEYS (already handled above)
        
        fix_untranslated(en, data)
        
        # Save
        save_json(lang, data)
        stats[lang] = changes
    
    # Print stats
    print("Translation fix results:")
    for lang, changes in sorted(stats.items(), key=lambda x: -x[1]):
        print(f"  {lang}: {changes} fixes")
    
    # Count remaining
    print("\nRemaining untranslated keys:")
    for lang in lang_codes:
        data = load_json(lang)
        count = 0
        def count_same(en_obj, lang_obj, prefix=''):
            nonlocal count
            for k, v in en_obj.items():
                full_key = f'{prefix}.{k}' if prefix else k
                if isinstance(v, dict):
                    if k in lang_obj and isinstance(lang_obj[k], dict):
                        count_same(v, lang_obj[k], full_key)
                else:
                    if k in lang_obj and lang_obj[k] == v and v:
                        count += 1
        count_same(en, data)
        if count > 0:
            print(f"  {lang}: {count}")

if __name__ == '__main__':
    fix_all_translations()
